def main():
    data = base64.b64decode("".join(PAYLOAD.split()))
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        z.extractall(".")
    print("Unpacked", len(z.namelist()), "entries into", os.getcwd())
    if "--extract-only" in sys.argv:
        return
    pkgs = ("build-essential binutils-arm-none-eabi gcc-arm-none-eabi libnewlib-arm-none-eabi "
            "git libpng-dev python3 python3-pip xvfb mgba-sdl")
    print("Installing toolchain (sudo apt)...")
    subprocess.call("sudo apt-get update && sudo apt-get install -y " + pkgs, shell=True)
    env = dict(os.environ, WORK=os.getcwd())
    rc = subprocess.call(["bash", "sandbox_kit/build_and_test.sh"], env=env)
    print("\nDone (exit %d). Upload build.log, install.log and debug_report.txt; play the newest giovanni_*.gba." % rc)

if __name__ == "__main__":
    main()
